import{getWrapper as t,postWrapper as o}from"fetch";import{$submitBtn as n}from"loading";import{createToast as e}from"toast";export const $contactBtn=document.getElementById("contactBtn");export async function getContactForm(){return await t({url:"/contact",$loadingDiv:null,loading:"",dataHandler:t=>{const a=document.createElement("div");a.innerHTML=t,document.getElementById("loadedModal").appendChild(a),globalModals.$contactFormModal=new bootstrap.Modal(document.getElementById("contactFormModal"),{});const c=document.getElementById("contactForm"),d=document.getElementById("submitContactForm");d.addEventListener("click",async t=>{const a=c.checkValidity();if(c.classList.add("was-validated"),!a)return t.preventDefault(),void t.stopPropagation();document.getElementById("closeContactForm").disabled=!0;const l=new FormData(c),r=Object.fromEntries(l.entries());await async function submitContactForm(t,a){return await o({url:"/home/contact",$loadingBtn:a,loading:n,packet:JSON.stringify(t),responseType:"json",dataHandler:()=>{globalModals.$contactFormModal.hide(),e("Email sent! Thanks for contacting us!","success","bi-check-square-fill")}})}(r,d)})}})}